argv:
$ErrorActionPreference='Stop';
$root=Join-Path $env:LOCALAPPDATA 'AgentOS';
$watchdog=Join-Path $root 'scripts\thin_client_watchdog.ps1';
$thin=Join-Path $root 'agentos_node\thin_client.py';
Invoke-WebRequest -UseBasicParsing -Uri 'https://raw.githubusercontent.com/alston-personal/agentmanager/fix/windows-thin-client-watchdog/scripts/windows/thin_client_watchdog.ps1' -OutFile $watchdog;
Invoke-WebRequest -UseBasicParsing -Uri 'https://raw.githubusercontent.com/alston-personal/agentmanager/feat/desktop-demo-recorder/agentos_node/thin_client.py' -OutFile $thin;
Stop-ScheduledTask -TaskName 'AgentOS Thin Client Watchdog' -ErrorAction SilentlyContinue;
Start-ScheduledTask -TaskName 'AgentOS Thin Client Watchdog';
[pscustomobject]@{watchdog=$watchdog;watchdog_bytes=(Get-Item $watchdog).Length;thin_client=$thin;thin_client_bytes=(Get-Item $thin).Length;watchdog_state=(Get-ScheduledTask -TaskName 'AgentOS Thin Client Watchdog').State}|ConvertTo-Json -Compress
